    <script id="ui-e-highlighted-text-js" src="{{ asset('assets/wikrama/js/highlighted-text.js') }}"></script>
    <script>
    document.addEventListener('DOMContentLoaded', function () {
        const animElements = document.querySelectorAll('.elementor-invisible');

        function triggerAnimation(el) {
            if (!el || !el.classList.contains('elementor-invisible')) return;

            let animName = 'fadeInLeft';
            const settings = el.getAttribute('data-settings');
            if (settings) {
                try {
                    const parsed = JSON.parse(settings);
                    if (parsed.animation) animName = parsed.animation;
                } catch(e) {}
            }
            el.classList.remove('elementor-invisible');
            el.classList.add('animated', animName);
        }

        if ('IntersectionObserver' in window) {
            const observer = new IntersectionObserver((entries, obs) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        triggerAnimation(entry.target);
                        obs.unobserve(entry.target);
                    }
                });
            }, {
                root: null,
                rootMargin: '0px 0px -40px 0px',
                threshold: 0.08
            });

            animElements.forEach(el => observer.observe(el));
        } else {
            animElements.forEach(el => triggerAnimation(el));
        }

        // Safety fallback: reveal any still hidden elements after 600ms
        setTimeout(function () {
            document.querySelectorAll('.elementor-invisible').forEach(el => triggerAnimation(el));
        }, 600);
    });
    </script>
@endpush
